TLM.f("Tempora/Adv1-1",{"officium":"Feria II infra Hebdomadam I Adventus","rule":["Oratio Dominica","no Gloria","no Credo","Suffr=Maria1;Ecclesiæ,Papa;;"],"ruleInherited":["no Gloria","Credo","Suffr=Maria1;Ecclesiæ,Papa;;"],"fallback":"Tempora/Adv1-0","from":{"Introitus":"Tempora/Adv1-0","Oratio":"Tempora/Adv1-0","Lectio":"Tempora/Adv1-0","Graduale":"Tempora/Adv1-0","GradualeF":"Tempora/Adv1-0","Evangelium":"Tempora/Adv1-0","Offertorium":"Tempora/Adv1-0","Secreta":"Tempora/Adv1-0","Communio":"Tempora/Adv1-0","Postcommunio":"Tempora/Adv1-0"},"sections":{"Introitus":[{"k":"ref","la":"Ps 24:1-3"},{"k":"text","la":"Ad te levávi ánimam meam: Deus meus, in te confído, non erubéscam: neque irrídeant me inimíci mei: étenim univérsi, qui te exspéctant, non confundéntur."},{"k":"ref","la":"Ps 24:4"},{"k":"text","la":"Vias tuas, Dómine, demónstra mihi: et sémitas tuas édoce me."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Ad te levávi ánimam meam: Deus meus, in te confído, non erubéscam: neque irrídeant me inimíci mei: étenim univérsi, qui te exspéctant, non confundéntur."}],"Oratio":[{"k":"text","la":"Excita, quǽsumus, Dómine, poténtiam tuam, et veni: ut ab imminéntibus peccatórum nostrórum perículis, te mereámur protegénte éripi, te liberánte salvári:"},{"k":"macro","name":"Qui vivis"}],"Lectio":[{"k":"text","la":"Lectio Epístolæ beáti Pauli Apóstoli ad Romános"},{"k":"ref","la":"Rom 13:11-14"},{"k":"text","la":"Fratres: Sciéntes, quia hora est jam nos de somno súrgere. Nunc enim própior est nostra salus, quam cum credídimus. Nox præcéssit, dies autem appropinquávit. Abjiciámus ergo ópera tenebrárum, et induámur arma lucis. Sicut in die honéste ambulémus: non in comessatiónibus et ebrietátibus, non in cubílibus et impudicítiis, non in contentióne et æmulatióne: sed induímini Dóminum Jesum Christum."}],"Graduale":[{"k":"ref","la":"Ps 24:3; 24:4"},{"k":"text","la":"Univérsi, qui te exspéctant, non confundéntur, Dómine."},{"k":"text","la":"Vias tuas, Dómine, notas fac mihi: et sémitas tuas édoce me. Allelúja, allelúja.","mark":"V"},{"k":"ref","la":"Ps 84:8"},{"k":"text","la":"Osténde nobis, Dómine, misericórdiam tuam: et salutáre tuum da nobis. Allelúja.","mark":"V"}],"GradualeF":[{"k":"ref","la":"Ps 24:3; 24:4"},{"k":"text","la":"Univérsi, qui te exspéctant, non confundéntur, Dómine."},{"k":"text","la":"Vias tuas, Dómine, notas fac mihi: et sémitas tuas édoce me.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secundum Lucam"},{"k":"ref","la":"Luc 21:25-33"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis: Erunt signa in sole et luna et stellis, et in terris pressúra géntium præ confusióne sónitus maris et flúctuum: arescéntibus homínibus præ timóre et exspectatióne, quæ supervénient univérso orbi: nam virtútes cœlórum movebúntur. Et tunc vidébunt Fílium hóminis veniéntem in nube cum potestáte magna et majestáte. His autem fíeri incipiéntibus, respícite et leváte cápita vestra: quóniam appropínquat redémptio vestra. Et dixit illis similitúdinem: Vidéte ficúlneam et omnes árbores: cum prodúcunt jam ex se fructum, scitis, quóniam prope est æstas. Ita et vos, cum vidéritis hæc fíeri, scitóte, quóniam prope est regnum Dei. Amen, dico vobis, quia non præteríbit generátio hæc, donec ómnia fiant. Cœlum et terra transíbunt: verba autem mea non transíbunt."}],"Offertorium":[{"k":"ref","la":"Ps 24:1-3"},{"k":"text","la":"Ad te levávi ánimam meam: Deus meus, in te confído, non erubéscam: neque irrídeant me inimíci mei: étenim univérsi, qui te exspéctant, non confundéntur."}],"Secreta":[{"k":"text","la":"Hæc sacra nos, Dómine, poténti virtúte mundátos ad suum fáciant purióres veníre princípium."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Ps 84:13"},{"k":"text","la":"Dóminus dabit benignitátem: et terra nostra dabit fructum suum."}],"Postcommunio":[{"k":"text","la":"Suscipiámus, Dómine, misericórdiam tuam in médio templi tui: ut reparatiónis nostræ ventúra sollémnia cóngruis honóribus præcedámus."},{"k":"macro","name":"Per Dominum"}]},"hr":{"72695dda34919179":{"t":"<i>Pomolimo se</i>.\nPokreni, molimo, Gospodine, svoju silu i dođi, da nas od pogibli naših grijeha, što nam prijete, tvoja zaštita izbavi, tvoje oslobođenje spasi:\n<i>koji živiš i kraljuješ s Bogom Ocem u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"(Oremus). Molimo Te, Gospodine, probudi svoju moć i dođi da nas izbaviš od pogibli naših grijeha, koje nam prijete, te nas, oslobođene,^ Tvojom zaštitom privedi k spasenju; koji živiš i kra. Ijuješ s Bogom Ocem u jedinstvu Duha Svetoga, Bog, po sve v'ijeke vjekova. Amen.","knRef":"Kniewald 1942, str. 34–35 (snimka 18) (OCR)"},"522c606bbf00485e":{"t":"Ovi sveti darovi neka nas, Gospodine, očiste svojom silnom moću, da nas čiste dovedu k svojemu Stvoritelju.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"52ff2f80a413d43c":{"t":"<i>Pomolimo se</i>.\nDaj, Gospodine, da primimo milosrđe u tvojemu hramu, da našim dostojnim štovanjem idemo ususret skorim blagdanima našeg otkupljenja.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Molinao Te, Gospodine, da primimo Tvoje milosrđe usred Tvoga hrama; te se dostojnim poštivanjem pripravimo za skore svetkovine našega spasenja; po G. n. I. K., Sinu Tvojemu, koji s Tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog, p;o sve vijeke vjekova. Amen.","knRef":"Kniewald 1942, str. 36–37 (snimka 19) (OCR)"},"8519a1975e5a27dc":{"t":"Ps 24, 1-4\nK tebi, Bože moj, uzdižem svoju dušu, u tebe se uzdam. Ne daj da se postidim. Neka mi se ne rugaju neprijatelji, jer se neće smesti nitko od onih koji tebe čekaju. Pokaži mi, Gospodine, svoje putove i nauči me svojim stazama.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\nK tebi, Bože moj, uzdižem svoju dušu, u tebe se uzdam. Ne daj da se postidim. Neka mi se ne rugaju neprijatelji, jer se neće smesti nitko od onih koji tebe čekaju."},"46278859600ea5f0":{"t":"Rim 13, 11-14\nČitanje Poslanice bl. Pavla apostola Rimljanima. Braćo: znate da je već doba da se probudimo. Sada je naše spasenje bliže nego kad smo primili vjeru. Odmakla je noć, približio se dan. Stoga odbacimo djela tame i oboružajmo se svjetlošću! Živimo pošteno kao po danu, ne u proždrijivosti i pijanstvu, ne u bludnosti i nečistoći, ne u svađi i zavisti, nego se obucite u Gospodina Isusa Krista.","kn":"Čitanje poslanice bi. Pavla apostola Rimljanin (13 11-14). Braćo! Znate, već je doba da se probudimo, jer je naš spas bliže sada, nego kada povjerovasmo. Noć je odmakla, a približio se dam Za o odbacimo tamna djela i oboružajmo £6_ svjetlošću. Živimo pošteno kao po danu, ne u proždrljivosti i 3S pijanstvu, ne u ložnicama i nečistoći, ne u svađi i zavisti, nego obucite se u Gospodina Isusa Krista.","knRef":"Kniewald 1942, str. 34–35 (snimka 18) (OCR)"},"fa04814357b0b1fe":{"t":"Ps 24, 3-4\nGospodine, neće se smesti nitko od onih koji tebe čekaju. Pokaži mi, Gospodine, svoje putove i nauči me svojim stazama.","kn":"(Ps. 24, 3-4). Gospodine, tko Tebe čeka, ne će se zastidjeti. Pokaži mi, Go^pdine, puto-ve svoje, uči me ići stazama tvojim.","knRef":"Kniewald 1942, str. 34–35 (snimka 18) (OCR)"},"9c5b0a6b0b46ce3d":{"t":"Lk 21, 25-33\nSlijedi sveto Evanđelje po Luki. U ono vrijeme reče Isus svojim učenicima: Bit će znaci na suncu i mjesecu i zvijezdama, a tjeskoba na zemlji među narodima, zbog silne buke mora i valova. Ljudi će umirati od straha i očekivanja onoga što će doći na sav svijet, jer će se pokrenuti nebeske sile. I tada će vidjeti Sina čovječjega gdje dolazi na oblacima s velikom moći i slavom. Kad se ovo počne događati, ohrabrite se i podignite svoje glave, jer se približuje vaše otkupljenje. I reče im usporedbu: Gledajte smokvu i sva stabla. Kad propupaju, znate da je blizu ljeto. Tako i vi kad opazite da se sve ovo događa, znajte da je blizu Božje kraljevstvo. Zaista vam kažem: Ovaj naraštaj neće proći dok se sve ovo ne ispuni. Nebo će i zemlja proći, ali riječi moje neće proći.","kn":"t Slijedi sv. evanđelje po Lnki (21, 25-33). U ono vrijeme reče Isus svojim učenicima; Bit će znaci na suncu i. mjesecu i zvijezdama, a na zemlji i među narodima tjeskoba radi silne buke mora i valova. Ljudi će ginuti od straha i očekivanja onoga, što će doći na sav svijet. Jer će se pokrenuti nebeske sile, i tada će vidjeti Sina čovječjega, gdje dolazi na oblaku s velikom moću i slavom. Kad se ovo počne događati, ohrabrite se i dignite svoje glave, jer se približuje vaš otkup. I reče im prispodobu: Gledajte smokvu i sve drveće! Kad već počne iz sebe izvoditi plod, znate, da je blizu ljeto. Tako i vi, kad vidite, da se ovo događa, znajte, da je blizu kraljevstvo Božje. Zaista vam kažem, da ovaj naraštaj ne će proći, dok se sve ne ispuni. Nebo će i zemlja proći, ali ne će proći moje riječi.","knRef":"Kniewald 1942, str. 34–35 (snimka 18) (OCR)"},"b177af858286647d":{"t":"Ps 24, 1-3\nK tebi, Bože moj, uzdižem svoju dušu, u tebe se uzdam. Ne daj da se postidim. Neka mi se ne rugaju neprijatelji, jer se neće smesti nitko od onih koji tebe čekaju.","kn":"(Ps. 24, 1-3). K Tebi, Gospodme, dižem dušu svoju. Bože moj, u Te se ufam, ne daj, da se zastidim i da mi se podsmijevaju neprijatelji moji! Ne, nitko od onih, koji Te čekaju, ne će se zastidjeti!","knRef":"Kniewald 1942, str. 102–103 (snimka 52) (OCR)"},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Predslovlje. Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti, Oče svemogući, vjećni Bože, po Kristu, Gospodinu našemu, po kome veličanstvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti. Nebesa Te i nebeske moći i . blaženi Serafini zadružnim klicanjem zajedno slave. Zapovjedi, molimo, da se i naši glasovi združe s njihovima, smjernim ispovijedanjem govoreći:","knRef":"Kniewald 1942, str. 758–759 (snimka 380) (OCR)"},"97aa204ed355b47f":{"t":"Ps 84, 13\nGospodin će dati blagoslov i naša će zemlja donijeti svoj rod.","kn":"(Ps. 84, 13). Gospodin će dati svoj blagoslov, a , zemlja će naša dali plod svoj.","knRef":"Kniewald 1942, str. 36–37 (snimka 19) (OCR)"}}});
